/* ===== Plan.js ===== */
/**
 * Plan.gs — the "what Campus Control currently plans" snapshot for a date window.
 * READ-ONLY: CMS `Schedule` tab (frozen column positions) + the Staff Events / HCS Events calendars.
 */

// { start, end, days:[{date, dow, door, church, bell, source, reason}], events:[{calendar, date, endDate,
//   allDay, start, end, title, tags}] } for [emailDate - lookback, emailDate + lookahead].
function mcPlanSnapshot_(anchorDate) {
  var start = _mcAddDays_(anchorDate, -MC_LOOKBACK_DAYS);
  var end   = _mcAddDays_(anchorDate,  MC_LOOKAHEAD_DAYS);
  return { start: start, end: end, days: mcScheduleRows_(start, end), events: mcCalendarEvents_(start, end) };
}

function mcScheduleRows_(start, end) {
  var sh = SpreadsheetApp.openById(MC_CMS_SHEET_ID).getSheetByName(MC_CMS_SCHEDULE_TAB);
  if (!sh) return [];
  var v = sh.getDataRange().getValues();
  var out = [];
  for (var r = 1; r < v.length; r++) {
    var ds = _mcCellDate_(v[r][MC_C_DATE]);
    if (!ds || ds < start || ds > end) continue;
    out.push({
      date: ds, dow: _mcDow_(ds),
      door:   String(v[r][MC_C_DOOR]   || '').trim(),
      church: String(v[r][MC_C_CHURCH] || '').trim(),
      bell:   String(v[r][MC_C_BELL]   || '').trim(),
      source: String(v[r][MC_C_SOURCE] || '').trim(),
      reason: String(v[r][MC_C_REASON] || '').trim()
    });
  }
  out.sort(function(a, b){ return a.date < b.date ? -1 : a.date > b.date ? 1 : 0; });
  return out;
}

function mcCalendarEvents_(start, end) {
  var from = new Date(start + 'T00:00:00'), to = new Date(_mcAddDays_(end, 1) + 'T00:00:00');
  var out = [];
  MC_CALENDARS.forEach(function(c) {
    var cal = null;
    try { cal = CalendarApp.getCalendarById(c.id); } catch (e) {}
    if (!cal) { out.push({ calendar: c.name, error: 'calendar not readable' }); return; }
    cal.getEvents(from, to).forEach(function(ev) {
      var desc = String(ev.getDescription() || '');
      var tags = [];
      desc.split('\n').forEach(function(l) {
        if (/^(Door Schedule|Bell Schedule|Doors|Unlock Start|Unlock End|dismissal|say|zone)\s*:/i.test(l.trim())) tags.push(l.trim().slice(0, 120));
      });
      var allDay = ev.isAllDayEvent();
      var endD = allDay ? _mcAddDays_(_mcFmt_(ev.getEndTime()), -1) : _mcFmt_(ev.getEndTime());
      out.push({
        calendar: c.name,
        date: _mcFmt_(ev.getStartTime()),
        endDate: endD,
        allDay: allDay,
        start: allDay ? '' : _mcFmt_(ev.getStartTime(), 'HH:mm'),
        end:   allDay ? '' : _mcFmt_(ev.getEndTime(),   'HH:mm'),
        title: String(ev.getTitle() || '').trim(),
        tags: tags
      });
    });
  });
  out.sort(function(a, b){ return (a.date + a.start) < (b.date + b.start) ? -1 : 1; });
  return out;
}

// Compact text rendering of the snapshot for the prompt (and for the log).
function mcPlanText_(plan) {
  var L = ['PLAN WINDOW ' + plan.start + ' .. ' + plan.end, '', 'CMS Schedule (per date: door type | church | bell schedule | source | reason):'];
  if (!plan.days.length) L.push('  (no published rows in window — CMS publish may be stalled)');
  plan.days.forEach(function(d) {
    L.push('  ' + d.date + ' ' + d.dow + ' | door=' + (d.door || '-') + ' | church=' + (d.church || '-') +
           ' | bell=' + (d.bell || '-') + ' | ' + d.source + (d.reason ? ' | ' + d.reason : ''));
  });
  L.push('', 'Calendar events in window (calendar | date | time | title | automation tags):');
  if (!plan.events.length) L.push('  (none)');
  plan.events.forEach(function(e) {
    if (e.error) { L.push('  ' + e.calendar + ': ' + e.error); return; }
    L.push('  ' + e.calendar + ' | ' + e.date + (e.endDate !== e.date ? '..' + e.endDate : '') +
           ' | ' + (e.allDay ? 'all-day' : e.start + '-' + e.end) + ' | ' + e.title +
           (e.tags.length ? ' | ' + e.tags.join('; ') : ''));
  });
  return L.join('\n');
}

/* ===== Queue.js ===== */
/**
 * Queue.gs — Phase 3 web app: Approve / Deny / Modify over the Findings queue.
 *
 * Deployed executeAs USER_DEPLOYING (itscripts@), access DOMAIN, so Session.getActiveUser() is the signed-in
 * staff member. Anyone in the domain can READ the queue; Approve / Deny / Modify buttons appear only for
 * holders of the CMS Permissions tab flag `ScheduleOverrides` (the same people who can make the change in
 * Eagle Eye) or the super-admin. Writes ONLY the Memo Check sheet. Applying a change is always a human
 * clicking in Eagle Eye; Applied.gs then verifies the plan and marks the row applied.
 */

function doGet(e) {
  var email = mcActiveUser_();
  var t = HtmlService.createTemplateFromFile('QueuePage');   // not 'Queue': Apps Script forbids a .gs and .html sharing a base name
  t.boot = JSON.stringify(mcQueueBootstrap_(email, (e && e.parameter && e.parameter.id) || ''));
  return t.evaluate()
    .setTitle('Memo Check — proposed changes')
    .addMetaTag('viewport', 'width=device-width, initial-scale=1')
    .setXFrameOptionsMode(HtmlService.XFrameOptionsMode.DEFAULT);
}

function mcActiveUser_() {
  var e = '';
  try { e = Session.getActiveUser().getEmail(); } catch (x) {}
  return String(e || '').trim().toLowerCase();
}

// Read-only lookup in the CMS Permissions tab. Fail closed: any read problem = no buttons.
function mcCanDecide_(email) {
  if (!email) return false;
  if (email === MC_SUPER_ADMIN) return true;
  try {
    var sh = SpreadsheetApp.openById(MC_CMS_SHEET_ID).getSheetByName(MC_CMS_PERMISSIONS_TAB);
    if (!sh || sh.getLastRow() < 2) return false;
    var v = sh.getDataRange().getValues();
    var h = {}; v[0].forEach(function(x, i){ h[String(x).trim().toLowerCase()] = i; });
    if (h.email === undefined || h[MC_CMS_PERM_FLAG.toLowerCase()] === undefined) return false;
    for (var r = 1; r < v.length; r++) {
      if (String(v[r][h.email]).trim().toLowerCase() === email) return String(v[r][h[MC_CMS_PERM_FLAG.toLowerCase()]]).trim().toUpperCase() === 'TRUE';
    }
  } catch (e) { Logger.log('[memo-check] permission lookup failed: ' + e); }
  return false;
}

// Per-user action token (house pattern from event-requests): CacheService, 30 min, rotated on every use.
function mcQueueToken_(email) {
  var c = CacheService.getScriptCache(), k = 'mcq_' + email, t = c.get(k);
  if (!t) { t = Utilities.getUuid(); c.put(k, t, 1800); }
  return t;
}
function mcQueueCheckToken_(email, token) {
  var c = CacheService.getScriptCache(), k = 'mcq_' + email, cur = c.get(k);
  if (!cur || !token || cur !== token) return null;
  var next = Utilities.getUuid(); c.put(k, next, 1800);
  return next;
}

function mcQueueBootstrap_(email, focusId) {
  var canDecide = mcCanDecide_(email);
  var cutoff = _mcAddDays_(_mcToday_(), -MC_QUEUE_DAYS_BACK);
  var rows = mcFindingsRows_().filter(function(r){ return String(r.CreatedAt).slice(0, 10) >= cutoff || r.Status === MC_ST.PROPOSED || r.Status === MC_ST.APPROVED; })
    .map(mcQueueRow_);
  rows.sort(function(a, b){ return a.date < b.date ? -1 : a.date > b.date ? 1 : (a.createdAt < b.createdAt ? -1 : 1); });
  return {
    user: email, canDecide: canDecide, token: canDecide ? mcQueueToken_(email) : '',
    eagleEyeUrl: MC_EAGLE_EYE_URL, focusId: String(focusId || ''), today: _mcToday_(),
    doorGroups: Object.keys(MC_DOORS), doors: MC_DOORS, rows: rows
  };
}

function mcQueueRow_(r) {
  var p = {};
  try { p = JSON.parse(r.ActionParams || '{}') || {}; } catch (e) {}
  var doors = [].concat(p.doors || []), groups = _mcDoorGroupsFor_(doors.length ? doors : (p.buildings || []));
  return {
    id: r.Id, status: r.Status, createdAt: r.CreatedAt, emailDate: r.EmailDate, from: r.From, subject: r.Subject,
    permalink: r.MessageId ? 'https://mail.google.com/mail/u/0/#all/' + r.MessageId : '',
    date: r.Date, endDate: r.EndDate, dow: r.Date ? _mcDow_(r.Date) : '', category: r.Category,
    quote: r.Quote, interpretation: r.Interpretation, planNow: r.PlanNow, gap: r.Gap === 'TRUE',
    action: r.Action, params: p, actionLabel: mcActionLabel_({ action: r.Action, action_params: r.ActionParams }),
    steps: r.EagleEyeSteps, groups: groups, confidence: r.Confidence,
    decidedBy: r.DecidedBy, decidedAt: r.DecidedAt, note: r.Note
  };
}

// Called from the page. decision: 'approve' | 'deny' | 'modify' | 'reopen'. params only for 'modify'.
function mcQueueDecide(req) {
  var email = mcActiveUser_();
  if (!mcCanDecide_(email)) return { ok: false, error: 'You can view the queue, but only Eagle Eye schedule editors can decide.' };
  var next = mcQueueCheckToken_(email, req && req.token);
  if (!next) return { ok: false, error: 'Your session token expired — reload the page.' };
  var id = String(req.id || ''), decision = String(req.decision || ''), note = String(req.note || '').trim();
  var rows = mcFindingsRows_().filter(function(r){ return r.Id === id; });
  if (!rows.length) return { ok: false, error: 'Unknown queue id ' + id, token: next };
  var r = rows[rows.length - 1], now = _mcFmt_(new Date(), 'yyyy-MM-dd HH:mm:ss');
  var patch = {};

  if (decision === 'approve' || decision === 'modify') {
    // Approve = "Set up & approve": the page sends the finalized setup (date, times, doors, title...).
    // An approved row can be re-edited until it is applied.
    if (r.Status === MC_ST.APPLIED) return { ok: false, error: 'Already applied — change it in Eagle Eye instead.', token: next };
    if (r.Status !== MC_ST.PROPOSED && r.Status !== MC_ST.DENIED && r.Status !== MC_ST.APPROVED) return { ok: false, error: 'This row cannot be approved.', token: next };
    patch = { Status: MC_ST.APPROVED, DecidedBy: email, DecidedAt: now };
    var hasSetup = req.params && Object.keys(req.params).length;
    if (hasSetup || (req.date && req.date !== r.Date) || (req.endDate && req.endDate !== (r.EndDate || r.Date))) {
      var v = mcQueueValidateParams_(r.Action, req.params || {}, req.date || r.Date, req.endDate || req.date || r.EndDate || r.Date);
      if (!v.ok) return { ok: false, error: v.error, token: next };
      var newParams = JSON.stringify(v.params);
      var changed = newParams !== r.ActionParams || v.date !== r.Date || v.endDate !== (r.EndDate || r.Date);
      patch.ActionParams = newParams; patch.Date = v.date; patch.EndDate = v.endDate;
      patch.Note = mcAppendNote_(r, (r.Status === MC_ST.APPROVED ? 're-' : '') + 'approved' +
        (changed ? ' with changes (was ' + r.Date + (r.EndDate && r.EndDate !== r.Date ? '..' + r.EndDate : '') + ' ' + r.ActionParams + ')' : '') + (note ? ': ' + note : ''));
    } else {
      patch.Note = mcAppendNote_(r, 'approved' + (note ? ': ' + note : ''));
    }
  } else if (decision === 'deny') {
    if (!note) return { ok: false, error: 'A reason is required to deny.', token: next };
    if (r.Status === MC_ST.APPLIED) return { ok: false, error: 'Already applied — change it in Eagle Eye instead.', token: next };
    patch = { Status: MC_ST.DENIED, DecidedBy: email, DecidedAt: now, Note: mcAppendNote_(r, 'denied: ' + note) };
  } else if (decision === 'reopen') {
    if (r.Status !== MC_ST.APPROVED && r.Status !== MC_ST.DENIED) return { ok: false, error: 'Only approved or denied rows can be reopened.', token: next };
    patch = { Status: MC_ST.PROPOSED, DecidedBy: '', DecidedAt: '', Note: mcAppendNote_(r, 'reopened by ' + email + ' ' + now) };
  } else {
    return { ok: false, error: 'Unknown decision ' + decision, token: next };
  }
  var updated = mcPatchFinding_(id, patch);
  return { ok: true, token: next, row: mcQueueRow_(updated) };
}

// Modify: accept only the fields each action actually has; everything else is rejected.
function mcQueueValidateParams_(action, params, date, endDate) {
  var ISO = /^\d{4}-\d{2}-\d{2}$/, HM = /^([01]?\d|2[0-3]):[0-5]\d$/;
  date = String(date || ''); endDate = String(endDate || date);
  if (!ISO.test(date)) return { ok: false, error: 'Date must be YYYY-MM-DD.' };
  if (!ISO.test(endDate) || endDate < date) return { ok: false, error: 'End date must be YYYY-MM-DD and not before the start.' };
  var out = {};
  switch (action) {
    case 'bells_ring_as':
      if (params.ringAs !== 'Thu' && params.ringAs !== 'Wed') return { ok: false, error: 'ringAs must be Thu or Wed.' };
      out.ringAs = params.ringAs; break;
    case 'early_release':
    case 'delay':
      if (String(params.hours) !== '2' && String(params.hours) !== '3') return { ok: false, error: 'hours must be 2 or 3.' };
      out.hours = Number(params.hours); break;
    case 'door_unlock':
      // start/end = the UNLOCK window (what the Door actually does; Applied.gs checks this).
      // eventStart/eventEnd = the event's own time on the calendar entry. title/location = calendar text.
      if (!HM.test(params.start || '') || !HM.test(params.end || '')) return { ok: false, error: 'Unlock start and end must be HH:MM.' };
      if (mcHHMM_(params.end) <= mcHHMM_(params.start)) return { ok: false, error: 'Doors must lock after they unlock (same day — overnight is not supported).' };
      if (params.eventStart || params.eventEnd) {
        if (!HM.test(params.eventStart || '') || !HM.test(params.eventEnd || '')) return { ok: false, error: 'Event start and end must be HH:MM.' };
        if (mcHHMM_(params.eventEnd) <= mcHHMM_(params.eventStart)) return { ok: false, error: 'The event must end after it starts.' };
        if (mcHHMM_(params.start) > mcHHMM_(params.eventStart) || mcHHMM_(params.end) < mcHHMM_(params.eventEnd))
          return { ok: false, error: 'The unlock window must cover the event (unlock at or before it starts, lock at or after it ends).' };
        out.eventStart = mcHHMM_(params.eventStart); out.eventEnd = mcHHMM_(params.eventEnd);
      }
      var all = []; Object.keys(MC_DOORS).forEach(function(g){ all = all.concat([g], MC_DOORS[g]); });
      var doors = [].concat(params.doors || []).map(String).filter(Boolean);
      if (!doors.length) return { ok: false, error: 'Pick at least one door group.' };
      for (var i = 0; i < doors.length; i++) if (all.indexOf(doors[i]) < 0) return { ok: false, error: 'Unknown door "' + doors[i] + '".' };
      out.start = mcHHMM_(params.start); out.end = mcHHMM_(params.end); out.doors = doors; out.buildings = _mcDoorGroupsFor_(doors);
      if (params.title)    out.title    = String(params.title).trim().slice(0, 100);
      if (params.location) out.location = String(params.location).trim().slice(0, 100);
      break;
    case 'exam_custom_span':
      out.start = date; out.end = endDate; break;
    case 'closure': case 'no_bells': case 'pa_dismissal':
      if (action === 'pa_dismissal') { if (!HM.test(params.time || '')) return { ok: false, error: 'time must be HH:MM.' }; out.time = mcHHMM_(params.time); }
      break;
    default:
      return { ok: false, error: 'This action cannot be modified here.' };
  }
  return { ok: true, params: out, date: date, endDate: endDate };
}

/** Editor helper: log who the active user resolves to and whether they may decide. */
function mcWhoCanDecide() {
  var e = mcActiveUser_();
  Logger.log('active user = %s · canDecide = %s · web app url = %s', e || '(none — run from the web app)', mcCanDecide_(e), _mcWebAppUrl_() || '(not deployed yet)');
}

