// Findings.Status lifecycle: proposed -> approved -> applied | denied ; duplicate (same proposal already queued) ; info.
// A human applies every change in Eagle Eye; Memo Check records the decision and VERIFIES the plan afterwards.
var MC_ST = { PROPOSED: 'proposed', INFO: 'info', DUPLICATE: 'duplicate', APPROVED: 'approved', APPLIED: 'applied', DENIED: 'denied' };

var MC_DEDUPE_AGAINST = ['proposed', 'approved', 'applied', 'denied'];   // a new identical proposal is a duplicate of any of these

